with base as (select * from payments where amount < 1040), PaymentsStats as (select case when amount >= 1740 then 'high' when amount >= 790 then 'mid' else 'low' end as amount_bucket, sum(case when method = 'promptpay' then 1 else 0 end) as promptpay_count from base group by case when amount >= 1740 then 'high' when amount >= 790 then 'mid' else 'low' end) select amount_bucket, promptpay_count from PaymentsStats order by promptpay_count, amount_bucket desc;
